# ----------------------------------------------------------
# 4) Utilidades geográficas
# ----------------------------------------------------------
def meter_offsets(lat):
    metros_lat = 111_320.0
    metros_lon = 111_320.0 * math.cos(math.radians(lat))
    return metros_lat, metros_lon

def rotated_rect(lat, lon, width_m, height_m, angle_deg=0):
    mlat, mlon = meter_offsets(lat)
    hx, hy = width_m / 2, height_m / 2
    a = math.radians(angle_deg)
    points = []

    for x, y in [(-hx,-hy),(hx,-hy),(hx,hy),(-hx,hy)]:
        xr = x * math.cos(a) - y * math.sin(a)
        yr = x * math.sin(a) + y * math.cos(a)
        points.append([lon + xr/mlon, lat + yr/mlat])

    return points

def rgba(tipo):
    return {
        "Facultad":[52,125,184,190],
        "Biblioteca":[76,175,80,205],
        "Posgrado":[123,104,238,195],
        "Servicio":[255,167,38,195],
        "Deporte":[38,166,154,185],
    }.get(tipo, [120,120,120,190])

def color_hex(tipo):
    return {
        "Facultad":"#347db8",
        "Biblioteca":"#4caf50",
        "Posgrado":"#7b68ee",
        "Servicio":"#ffa726",
        "Deporte":"#26a69a",
    }.get(tipo, "#777777")

def preparar_edificios(df):
    data = []
    for _, r in df.iterrows():
        data.append({
            **r.to_dict(),
            "polygon": rotated_rect(
                r["lat"], r["lon"], r["ancho_m"], r["largo_m"], r["angulo"]
            ),
            "color": rgba(r["tipo"]),
            "label": str(r["nombre"]).replace(" (DEMO)", "")
        })
    return data

